def gabung_interval(interval):
    interval.sort(key=lambda x: x[0])
    hasil = []
    for mulai, selesai in interval:
        if hasil and mulai <= hasil[-1][1]:
            hasil[-1][1] = max(hasil[-1][1], selesai)
        else:
            hasil.append([mulai, selesai])
    return hasil
